    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def components(color):
        seen, result = set(), []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack, comp = [(r, c)], []
                seen.add((r, c))
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            p = (y + dy, x + dx)
                            if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == color and p not in seen:
                                seen.add(p)
                                stack.append(p)
                result.append(comp)
        return result

    def diamond(cy, cx, radius, color):
        if radius == 0:
            if 0 <= cy < h and 0 <= cx < w:
                out[cy][cx] = color
            return
        for d in range(-radius, radius + 1):
            dx = radius - abs(d)
            for x in {cx - dx, cx + dx}:
                y = cy + d
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = color

    for color in (2, 5):
        for comp in components(color):
            for y, x in comp:
                out[y][x] = 7
            r0, r1 = min(y for y, x in comp), max(y for y, x in comp)
            c0, c1 = min(x for y, x in comp), max(x for y, x in comp)
            cy, cx = (r0 + r1) // 2, (c0 + c1) // 2
            radius = max((r1 - r0) // 2, (c1 - c0) // 2)
            if color == 5:
                if len(comp) == 1:
                    diamond(cy, cx, 1, 5)
                    out[cy][cx] = 7
                else:
                    diamond(cy, cx, radius + 1, 5)
            else:
                diamond(cy, cx, radius // 2, 2)
    return out
